}

#notes-container .note-tags-container {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-bottom: 1.25rem;
}

#notes-container .note-tag {
    font-size: 0.75rem;
    color: var(--text-secondary);
    background-color: var(--bg-primary);
    border: 1px solid var(--border-color);
    padding: 2px 8px;
    border-radius: 4px;
}

body.light-theme #notes-container .note-tag {
    background-color: #f1f5f9;
