import time
import http.server
import socketserver
import threading
from selenium import webdriver
from selenium.webdriver.chrome.options import Options

WORKSPACE = r"d:\GitHub\[oU1TS]\events"
PORT = 8987

class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=WORKSPACE, **kwargs)
    def log_message(self, format, *args):
        pass

server = socketserver.TCPServer(("", PORT), Handler)
t = threading.Thread(target=server.serve_forever, daemon=True)
t.start()

options = Options()
options.add_argument("--headless=new")
options.add_argument("--window-size=1280,800")
driver = webdriver.Chrome(options=options)

print("=== TEST 1: Full Duration Test (Expected: ~2.1s) ===")
driver.execute_cdp_cmd("Page.addScriptToEvaluateOnNewDocument", {
    "source": """
        window.__eventsLog = [];
        document.addEventListener('DOMContentLoaded', () => {
            const container = document.getElementById('raids-container');
            if (container) {
                const obs = new MutationObserver((mutations) => {
                    for (const m of mutations) {
                        if (m.type === 'attributes' && m.attributeName === 'class' && m.target.id === 'raid-card-22') {
                            window.__eventsLog.push({ time: performance.now(), type: 'class', detail: m.target.className });
                        }
                    }
                });
                obs.observe(container, { subtree: true, attributes: true, attributeFilter: ['class'] });
            }
        });
    """
})

driver.get(f"http://localhost:{PORT}/#raid-22")
time.sleep(3.5)

logs = driver.execute_script("return window.__eventsLog || [];")
start_time = None
end_time = None
for l in logs:
    if 'highlighted' in l['detail'] and start_time is None:
        start_time = l['time']
    elif 'highlighted' not in l['detail'] and start_time is not None and end_time is None:
        end_time = l['time']

if start_time and end_time:
    duration = end_time - start_time
    print(f"Highlight Pulse Start: {start_time:.1f}ms, End: {end_time:.1f}ms, Duration: {duration:.1f}ms (~{duration/1000:.2f}s)")
else:
    print("Could not measure duration from logs:", logs)

is_open_after = driver.execute_script("return document.getElementById('raid-card-22').open;")
print(f"Card open state after animation ended undisturbed: {is_open_after} (Expected: True)")


print("\n=== TEST 2: Manual Retract Toggle Stops Animation & Does Not Revert ===")
driver.get(f"http://localhost:{PORT}/#raid-22")
# Wait 400ms for highlight to be active
time.sleep(0.4)

is_highlighted_before = driver.execute_script("return document.getElementById('raid-card-22').classList.contains('highlighted');")
is_open_before = driver.execute_script("return document.getElementById('raid-card-22').open;")
print(f"Before manual toggle -> highlighted: {is_highlighted_before}, open: {is_open_before}")

# Click summary to manually close the card
driver.execute_script("""
    const summary = document.querySelector('#raid-card-22 summary');
    summary.click();
""")
time.sleep(0.1)

is_highlighted_immediately_after = driver.execute_script("return document.getElementById('raid-card-22').classList.contains('highlighted');")
is_open_immediately_after = driver.execute_script("return document.getElementById('raid-card-22').open;")
print(f"Immediately after manual toggle -> highlighted: {is_highlighted_immediately_after} (Expected: False), open: {is_open_immediately_after} (Expected: False)")

# Wait past the full 2.5s mark to ensure no pending re-render reverts it to open
time.sleep(2.5)

is_open_final = driver.execute_script("return document.getElementById('raid-card-22').open;")
is_highlighted_final = driver.execute_script("return document.getElementById('raid-card-22').classList.contains('highlighted');")
print(f"After 2.5s wait -> open: {is_open_final} (Expected: False - must NOT revert!), highlighted: {is_highlighted_final} (Expected: False)")

