import time
import http.server
import socketserver
import threading
from selenium import webdriver
from selenium.webdriver.chrome.options import Options

WORKSPACE = r"d:\GitHub\[oU1TS]\events"
PORT = 8986

class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=WORKSPACE, **kwargs)
    def log_message(self, format, *args):
        pass

server = socketserver.TCPServer(("", PORT), Handler)
t = threading.Thread(target=server.serve_forever, daemon=True)
t.start()

options = Options()
options.add_argument("--headless=new")
options.add_argument("--window-size=1280,800")
driver = webdriver.Chrome(options=options)

driver.get(f"http://localhost:{PORT}/#raids")
time.sleep(2.0)

disallowed = driver.execute_script("""
    const interactiveTags = ['A', 'BUTTON', 'INPUT', 'SELECT', 'TEXTAREA'];
    const summaries = Array.from(document.querySelectorAll('summary'));
    const results = [];

    summaries.forEach((s, sIdx) => {
        const interactiveChildren = Array.from(s.querySelectorAll(interactiveTags.join(',')));
        if (interactiveChildren.length > 0) {
            results.push({
                summaryIndex: sIdx,
                summaryClass: s.className,
                parentDetailsId: s.parentElement?.id,
                interactiveDescendants: interactiveChildren.map(c => ({
                    tag: c.tagName,
                    class: c.className,
                    text: c.innerText.trim(),
                    title: c.getAttribute('title')
                }))
            });
        }
    });
    return results;
""")

print(f"Summaries containing disallowed interactive descendants: {len(disallowed)}")
total_elements = 0
for d in disallowed:
    print(f"\nSummary #{d['summaryIndex']} (parent: {d['parentDetailsId']}, class: '{d['summaryClass']}'):")
    for child in d['interactiveDescendants']:
        total_elements += 1
        print(f"  - <{child['tag']}> class='{child['class']}' title='{child['title']}' text='{child['text']}'")

print(f"\nTotal disallowed elements found: {total_elements}")

driver.quit()
server.shutdown()

