args.Content:
const fs = require('fs');
const path = require('path');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';

['index.html', 'render.html'].forEach(file => {
    const filePath = path.join(repoDir, file);
    const html = fs.readFileSync(filePath, 'utf8');
    const inputMatches = [...html.matchAll(/<(input|select|textarea)([^>]*)>/gi)];
    console.log(`\n=== Checking ${file} (${inputMatches.length} form controls) ===`);
    inputMatches.forEach(m => {
        const tag = m[1];
        const attrs = m[2];
        if (/type=["']hidden["']/i.test(attrs)) return;
        const idMatch = attrs.match(/id=["']([^"']+)["']/i);
        const id = idMatch ? idMatch[1] : null;
        const hasAria = /aria-label|aria-labelledby/i.test(attrs);
        let hasLabel = false;
        if (id) {
            const labelRegex = new RegExp(`<label[^>]*for=["']${id}["']`, 'i');
            hasLabel = labelRegex.test(html);
        }
        if (!hasLabel && !hasAria) {
            console.log(`UNLABELED: <${tag} ${attrs.trim().replace(/\s+/g, ' ')}>`);
        }
    });
});

