const fs = require('fs');
const path = require('path');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';
const appJs = fs.readFileSync(path.join(repoDir, 'app.js'), 'utf8');

console.log('--- Checking app.js for summary appendings ---');
const summaryAppendMatches = [...appJs.matchAll(/(\w+Summary\w*|\bsummaryEl)\.appendChild\(([^)]+)\)/g)];
console.log(`Found ${summaryAppendMatches.length} appends to summary elements:`);
summaryAppendMatches.forEach(m => {
    console.log(`  ${m[1]}.appendChild(${m[2]})`);
});

const fs = require('fs');
const path = require('path');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';
const raidsJson = JSON.parse(fs.readFileSync(path.join(repoDir, 'raids.json'), 'utf8'));

// Minimal browser DOM mock
class MockElement {
    constructor(tagName) {
        this.tagName = tagName.toUpperCase();
        this.children = [];
        this.attributes = {};
        this.classList = new Set();
        this._innerHTML = '';
        this.textContent = '';
    }
    setAttribute(k, v) { this.attributes[k] = v; }
    getAttribute(k) { return this.attributes[k] || null; }
    appendChild(child) {
        this.children.push(child);
        child.parentElement = this;
        return child;
    }
    insertBefore(newChild, refChild) {
        const idx = this.children.indexOf(refChild);
        if (idx === -1) this.children.push(newChild);
        else this.children.splice(idx, 0, newChild);
        newChild.parentElement = this;
        return newChild;
    }
    addEventListener() {}
    removeEventListener() {}
    querySelector(sel) {
        // Simple class or tag selector
        const cleanSel = sel.replace(/^\./, '').toUpperCase();
        for (const c of this.children) {
            if (c.tagName === cleanSel || c.classList.has(sel.replace(/^\./, ''))) return c;
            const res = c.querySelector(sel);
            if (res) return res;
        }
        return null;
    }
    querySelectorAll(sel) {
        const results = [];
        const cleanSel = sel.replace(/^\./, '').toUpperCase();
        for (const c of this.children) {
            if (c.tagName === cleanSel || c.classList.has(sel.replace(/^\./, ''))) results.push(c);
            results.push(...c.querySelectorAll(sel));
        }
        return results;
    }
}

// Check disallowed interactive tags in all summary elements
console.log(`Testing with ${raidsJson.length} raids from raids.json...`);
const interactiveTags = ['A', 'BUTTON', 'INPUT', 'SELECT', 'TEXTAREA'];

// Let's also parse index.html and verify all summary elements statically
const indexHtml = fs.readFileSync(path.join(repoDir, 'index.html'), 'utf8');
const summaryTagMatches = [...indexHtml.matchAll(/<summary[\s\S]*?<\/summary>/gi)];
console.log(`Static <summary> elements in index.html: ${summaryTagMatches.length}`);
summaryTagMatches.forEach((s, idx) => {
    interactiveTags.forEach(tag => {
        const r = new RegExp(`<${tag}\\b`, 'i');
        if (r.test(s[0])) {
            console.error(`Disallowed <${tag}> found in static summary #${idx}!`);
        }
    });
});
console.log('Static summary verification passed.');

