const fs = require('fs');
const path = require('path');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';
const appJs = fs.readFileSync(path.join(repoDir, 'app.js'), 'utf8');

// Check that copyBtn is NOT appended to summaryEl or card, but to cardWrapper
const copyBtnAppends = [...appJs.matchAll(/(\w+)\.appendChild\(copyBtn\)/g)];
console.log('--- copyBtn append targets ---');
copyBtnAppends.forEach(m => {
    const target = m[1];
    const ok = target === 'cardWrapper';
    console.log(`  ${target}.appendChild(copyBtn) -> ${ok ? 'OK (wrapper, always visible)' : 'PROBLEM (hidden when collapsed!)'}`);
});

// Check that card toggle event guards against bubbled events from nested details
const toggleListeners = [...appJs.matchAll(/card\.addEventListener\('toggle'[\s\S]*?\}\);/g)];
console.log('\n--- card toggle listeners ---');
toggleListeners.forEach((m, i) => {
    const hasTargetGuard = m[0].includes('e.target !== card');
    console.log(`  Listener ${i}: target guard present = ${hasTargetGuard}`);
});

// Check that card is appended to cardWrapper, and cardWrapper to raidsContainer
const wrapperAppend = appJs.includes('cardWrapper.appendChild(card)');
const containerAppend = appJs.includes('raidsContainer.appendChild(cardWrapper)');
console.log(`\n--- DOM structure ---`);
console.log(`  cardWrapper.appendChild(card): ${wrapperAppend}`);
console.log(`  raidsContainer.appendChild(cardWrapper): ${containerAppend}`);

// Check for any remaining interactive elements appended to summaryEl
const summaryAppends = [...appJs.matchAll(/summaryEl\.appendChild\((\w+)\)/g)];
console.log('\n--- Elements appended to summaryEl ---');
summaryAppends.forEach(m => {
    const child = m[1];
    const isInteractive = ['copyBtn', 'editBtn'].includes(child);
    console.log(`  summaryEl.appendChild(${child}) -> ${isInteractive ? 'PROBLEM (interactive in summary!)' : 'OK'}`);
});

