const http = require('http');
const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';
const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';

const server = http.createServer((req, res) => {
    let reqPath = decodeURIComponent(req.url.split('?')[0]);
    if (reqPath === '/') reqPath = '/index.html';
    const filePath = path.join(repoDir, reqPath.replace(/^\//, ''));

    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
        const ext = path.extname(filePath).toLowerCase();
        const mimeTypes = {
            '.html': 'text/html',
            '.css': 'text/css',
            '.js': 'application/javascript',
            '.json': 'application/json',
            '.md': 'text/markdown',
            '.png': 'image/png',
            '.jpg': 'image/jpeg',
            '.svg': 'image/svg+xml'
        };
        res.writeHead(200, { 'Content-Type': mimeTypes[ext] || 'text/plain' });
        fs.createReadStream(filePath).pipe(res);
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

server.listen(8989, () => {
    console.log('Server listening on port 8989');

    const screenshotPath = 'C:\\Users\\gsmur\\.gemini\\antigravity\\brain\\e0f80055-2ee6-4cdd-a7ff-d55c40c73f62\\scratch\\render_test.png';
    const args = [
        '--headless=new',
        '--disable-gpu',
        '--window-size=1280,1024',
        `--screenshot=${screenshotPath}`,
        '--virtual-time-budget=5000',
        'http://localhost:8989/render.html?file=doc/notes/numo26.md'
    ];

    console.log('Running Chrome to take screenshot...');
    execFile(chromePath, args, (err, stdout, stderr) => {
        if (err) {
            console.error('Chrome error:', err);
        } else {
            console.log('Screenshot saved to', screenshotPath);
            console.log('File size:', fs.existsSync(screenshotPath) ? fs.statSync(screenshotPath).size : 'not found');
        }
        server.close();
    });
});

