const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const repoDir = 'd:\\GitHub\\[oU1TS]\\events';
const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';

const server = http.createServer((req, res) => {
    let reqPath = decodeURIComponent(req.url.split('?')[0]);
    if (reqPath === '/') reqPath = '/render.html';
    const filePath = path.join(repoDir, reqPath.replace(/^\//, ''));

    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
        const ext = path.extname(filePath).toLowerCase();
        const mimeTypes = {
            '.html': 'text/html',
            '.css': 'text/css',
            '.js': 'application/javascript',
            '.json': 'application/json',
            '.md': 'text/markdown',
            '.png': 'image/png'
        };
        res.writeHead(200, { 'Content-Type': mimeTypes[ext] || 'text/plain' });
        fs.createReadStream(filePath).pipe(res);
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

server.listen(8991, async () => {
    console.log('Server running on 8991');
    const chrome = spawn(chromePath, [
        '--headless=new',
        '--no-sandbox',
        '--disable-dev-shm-usage',
        '--disable-gpu',
        '--remote-debugging-port=9223',
        '--window-size=1280,800'
    ]);

    // Wait for Chrome debugging port
    await new Promise(r => setTimeout(r, 1500));

    try {
        const versionRes = await fetch('http://127.0.0.1:9223/json/list');
        const tabs = await versionRes.json();
        const wsUrl = tabs[0].webSocketDebuggerUrl;
        console.log('Connecting to WS:', wsUrl);

        const ws = new WebSocket(wsUrl);
        let id = 1;
        const pending = new Map();

        ws.onmessage = (msg) => {
            const data = JSON.parse(msg.data);
            if (data.id && pending.has(data.id)) {
                pending.get(data.id)(data);
                pending.delete(data.id);
            }
        };

        const send = (method, params = {}) => new Promise((resolve) => {
            const curId = id++;
            pending.set(curId, resolve);
            ws.send(JSON.stringify({ id: curId, method, params }));
        });

        await new Promise(r => ws.onopen = r);
        console.log('Connected to CDP');

        await send('Page.enable');
        await send('Runtime.enable');
        await send('Page.navigate', { url: 'http://localhost:8991/render.html?file=doc/notes/event_trackers_directory.md' });

        // Wait for page to render
        await new Promise(r => setTimeout(r, 2000));

        // Open TOC
        const evalRes = await send('Runtime.evaluate', {
            expression: `(function() {
                const toggle = document.getElementById('toc-toggle');
                if (toggle) toggle.click();
                const navPane = document.getElementById('nav-pane');
                const tocList = document.getElementById('toc-list');
                const links = Array.from(document.querySelectorAll('.toc-link'));
                const rects = links.map(l => {
                    const r = l.getBoundingClientRect();
                    return { text: l.textContent.trim(), top: r.top, bottom: r.bottom, height: r.height };
                });
                let overlaps = 0;
                for (let i = 0; i < rects.length - 1; i++) {
                    if (rects[i].bottom > rects[i+1].top + 0.5) {
                        overlaps++;
                    }
                }
                return {
                    navPaneClasses: navPane.className,
                    tocCount: links.length,
                    tocListHeight: tocList.getBoundingClientRect().height,
                    tocListScrollHeight: tocList.scrollHeight,
                    overlaps,
                    sampleRects: rects.slice(0, 10),
                    lastRects: rects.slice(-5)
                };
            })()`,
            returnByValue: true
        });

        console.log('TOC Evaluation Result:', JSON.stringify(evalRes.result?.value, null, 2));

        // Take screenshot
        const shotRes = await send('Page.captureScreenshot', { format: 'png' });
        fs.writeFileSync(path.join(__dirname, 'toc_screenshot.png'), Buffer.from(shotRes.result.data, 'base64'));
        console.log('Saved toc_screenshot.png');

        ws.close();
    } catch (e) {
        console.error('Error during CDP test:', e);
    } finally {
        chrome.kill();
        server.close();
    }
});

